              <button class="secondary" type="button">Download</button>
              <button class="trigger" type="button">Delete image</button>
            </div>
          </div>

          <p id="statusMessage" class="status" aria-live="polite"></p>
        </article>
      </section>
    </main>

    <dialog id="deleteDialog" aria-labelledby="dialog-title" aria-describedby="dialog-copy">
      <div class="dialog-inner">
        <span class="dialog-badge">Delete from library</span>
        <h2 id="dialog-title">Delete this image?</h2>
        <p id="dialog-copy">
          This will remove <strong>Midnight Horizon</strong> from your library. This
          action cannot be undone.
        </p>

        <div class="dialog-actions">
          <button id="cancelButton" class="secondary" type="button">Cancel</button>
          <button id="confirmButton" class="danger" type="button">Delete image</button>
        </div>
      </div>
    </dialog>

    <script>
      const trigger = document.querySelector(".trigger");
      const dialog = document.getElementById("deleteDialog");
      const cancelButton = document.getElementById("cancelButton");
      const confirmButton = document.getElementById("confirmButton");
      const statusMessage = document.getElementById("statusMessage");
      let restoreFocusTo = null;

      const closeDialog = () => {
        if (dialog.open) {
          dialog.close();
        }
      };

      trigger.addEventListener("click", () => {
        restoreFocusTo = document.activeElement;
        dialog.showModal();
        cancelButton.focus();
      });

      cancelButton.addEventListener("click", () => {
        statusMessage.textContent = "Deletion canceled.";
        closeDialog();
      });

      confirmButton.addEventListener("click", () => {
        statusMessage.textContent = "Image deleted from your library.";
        closeDialog();
      });

      dialog.addEventListener("cancel", (event) => {
        event.preventDefault();
        statusMessage.textContent = "Deletion canceled.";
        closeDialog();
      });

